const extracted = $("Extract Master CV").first().json;
const form = $("Submit Job").first().json;

const parseJson = (value) => {
  if (typeof value !== "string") return value;
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
};

const unwrapMasterCv = (value) => {
  let current = parseJson(value);

  for (let depth = 0; depth < 5; depth++) {
    if (!current || typeof current !== "object" || Array.isArray(current)) break;
    if (Array.isArray(current.projects)) return current;

    const next =
      current.master_cv ??
      current.cv_json ??
      current.document_data ??
      current.data ??
      current.json;

    if (next === undefined || next === current) break;
    current = parseJson(next);
  }

  return current;
};

const text = (value) => String(value ?? "").trim();
const masterCv = unwrapMasterCv(extracted);

if (!masterCv || typeof masterCv !== "object" || Array.isArray(masterCv)) {
  throw new Error("The master CV file must contain a JSON object.");
}
if (!Array.isArray(masterCv.projects)) {
  throw new Error("The master CV JSON could not be normalized: projects must be an array.");
}

const entryType = text(form.entryType || form["Entry Type"]);
if (entryType !== "External") {
  throw new Error(`Expected Entry Type External but received "${entryType}".`);
}

const companyName = text(form.companyName || form["Company Name"]);
const jobTitle = text(form.jobTitle || form["Job Title"]);
const jobDescription = text(form.jobDescription || form["Job Description"]);
const jobUrl = text(form.jobUrl || form["Job URL"]);

if (!companyName) throw new Error("Company Name is required for External entries.");
if (!jobTitle) throw new Error("Job Title is required for External entries.");
if (!jobDescription) throw new Error("Job Description is required for External entries.");
if (!jobUrl) throw new Error("Job URL is required for External entries.");

return [{
  json: {
    companyName,
    jobTitle,
    jobDescription,
    jobUrl,
    location: text(form.location || form["Location"]),
    contractType: text(form.contractType || form["Contract Type"]),
    publishedAt: text(form.publishedAt || form["Published Date"]),
    jobId: text(form.jobId || form["External Job ID"]),
    source: "External",
    master_cv: masterCv,
  },
  pairedItem: { item: 0 },
}];

const extracted = $("Extract Master CV").first().json;
const form = $("Submit Job").first().json;
const actorItems = $input.all().map((item) => item.json);

const parseJson = (value) => {
  if (typeof value !== "string") return value;
  try {
    return JSON.parse(value);
  } catch {
    return value;
  }
};

const unwrapMasterCv = (value) => {
  let current = parseJson(value);

  for (let depth = 0; depth < 5; depth++) {
    if (!current || typeof current !== "object" || Array.isArray(current)) break;
    if (Array.isArray(current.projects)) return current;

    const next =
      current.master_cv ??
      current.cv_json ??
      current.document_data ??
      current.data ??
      current.json;

    if (next === undefined || next === current) break;
    current = parseJson(next);
  }

  return current;
};

const firstValue = (source, names) => {
  for (const name of names) {
    const value = source?.[name];
    if (value !== undefined && value !== null && String(value).trim() !== "") {
      return value;
    }
  }
  return "";
};

const text = (value) => String(value ?? "").trim();
const masterCv = unwrapMasterCv(extracted);

if (!masterCv || typeof masterCv !== "object" || Array.isArray(masterCv)) {
  throw new Error("The master CV file must contain a JSON object.");
}
if (!Array.isArray(masterCv.projects)) {
  throw new Error("The master CV JSON could not be normalized: projects must be an array.");
}

const linkedinJobUrl = text(form.linkedinJobUrl || form["LinkedIn Job URL"]);
if (!linkedinJobUrl) {
  throw new Error("LinkedIn Job URL is required for LinkedIn entries.");
}
if (actorItems.length === 0) {
  throw new Error("The LinkedIn actor returned no job.");
}

return actorItems.map((job, index) => {
  const company =
    job.company && typeof job.company === "object"
      ? firstValue(job.company, ["name", "companyName", "title"])
      : job.company;

  const companyName = text(firstValue(job, [
    "companyName", "company_name", "company", "companyTitle", "organizationName"
  ]) || company);

  const jobTitle = text(firstValue(job, [
    "jobTitle", "job_title", "title", "position", "positionName"
  ]));

  const jobDescription = text(firstValue(job, [
    "jobDescription", "job_description", "description", "descriptionText", "text"
  ]));

  const jobUrl = text(firstValue(job, [
    "jobUrl", "job_url", "url", "link", "linkedinUrl", "jobPostingUrl"
  ]) || linkedinJobUrl);

  if (!companyName) throw new Error("The LinkedIn actor output is missing companyName.");
  if (!jobTitle) throw new Error("The LinkedIn actor output is missing jobTitle.");
  if (!jobDescription) throw new Error("The LinkedIn actor output is missing jobDescription.");
  if (!jobUrl) throw new Error("The LinkedIn actor output is missing jobUrl.");

  const locationValue =
    job.location && typeof job.location === "object"
      ? firstValue(job.location, ["formattedAddress", "name", "city"])
      : firstValue(job, ["location", "jobLocation", "locationName"]);

  return {
    json: {
      companyName,
      jobTitle,
      jobDescription,
      jobUrl,
      location: text(locationValue),
      contractType: text(firstValue(job, [
        "contractType", "contract_type", "employmentType", "employment_type", "jobType"
      ])),
      publishedAt: text(firstValue(job, [
        "publishedAt", "published_at", "postedAt", "posted_at", "datePosted", "publishedDate"
      ])),
      jobId: text(firstValue(job, [
        "jobId", "job_id", "id", "linkedinJobId", "externalId"
      ])),
      source: "LinkedIn",
      master_cv: masterCv,
    },
    pairedItem: { item: index },
  };
});

