const cvContent = $("Create Tailored CV Content").item.json;
const job = cvContent.source_job;

const cvPdf = $("Upload CV PDF to Baserow").first().json;
const cvTex = $("Upload CV TEX to Baserow").first().json;
const coverPdf = $("Upload Cover Letter PDF to Baserow").first().json;
const coverTex = $("Upload Cover Letter TEX to Baserow").first().json;

const requiredUpload = (upload, label) => {
  if (!upload || typeof upload.name !== "string" || !upload.name.trim()) {
    throw new Error(`${label} did not return a valid Baserow user-file name.`);
  }
  return upload;
};

requiredUpload(cvPdf, "CV PDF upload");
requiredUpload(cvTex, "CV TEX upload");
requiredUpload(coverPdf, "Cover letter PDF upload");
requiredUpload(coverTex, "Cover letter TEX upload");

const applicationId = String(cvContent.application_id ?? "application");

const dateValue = job.publishedAt
  ? String(job.publishedAt).slice(0, 10)
  : new Date().toISOString().slice(0, 10);

return [{
  json: {
    "Job ID": String(cvContent.job_id ?? ""),
    "Date": dateValue,
    "Company Name": job.companyName ?? "",
    "Title": job.jobTitle ?? "",
    "Location": job.location ?? "",
    "Job Description": job.jobDescription ?? "",
    "Contract Type": job.contractType ?? "",
    "Cover Letter": [
      {
        "name": coverPdf.name,
        "visible_name": `cover-letter_${applicationId}.pdf`
      },
      {
        "name": coverTex.name,
        "visible_name": `cover-letter_${applicationId}.tex`
      }
    ],
    "CV": [
      {
        "name": cvPdf.name,
        "visible_name": `cv_${applicationId}.pdf`
      },
      {
        "name": cvTex.name,
        "visible_name": `cv_${applicationId}.tex`
      }
    ],
    "Link": job.jobUrl ?? "",
    "Status": "New"
  }
}];

const submission = $input.first().json ?? {};
const questions = submission.questions ?? {};

const FIELD_IDS = {
  entryType: "entryType",
  linkedinJobUrl: "oghMWc6sfTWHCnUjHzN5PT",
  companyName: "tccyk1pB8iRUf1NGCDbcP5",
  jobTitle: "mV2wYQbu1b1Jhf1gTDAbK8",
  jobDescription: "98TcaL2qnS8Y31TQxgZaZD",
  jobUrl: "1gZ3kT2Db3G3y2QhYfjT8X",
  location: "oc63gzWN4vxEJwx8nzZrAK",
  contractType: "g2VK5MiabTgDTUXGYhnV4q",
  publishedAt: "sYghUzUtSwi8T4yaReYefR",
  jobId: "2XDTXJHaY2BJEndo3EgEAV",
};

const normalizeValue = (value) => {
  if (value === undefined || value === null) return "";

  if (Array.isArray(value)) {
    return value.map(normalizeValue).filter((item) => item !== "").join(", ");
  }

  if (typeof value === "object") {
    for (const key of ["value", "label", "name", "url", "text", "optionId", "id"]) {
      if (value[key] !== undefined && value[key] !== null) {
        return normalizeValue(value[key]);
      }
    }
    return JSON.stringify(value);
  }

  return String(value).trim();
};

const questionValue = (fieldId, expectedName) => {
  const direct = questions[fieldId];

  if (direct !== undefined) {
    if (direct && typeof direct === "object" && "value" in direct) {
      return normalizeValue(direct.value);
    }
    return normalizeValue(direct);
  }

  const match = Object.values(questions).find((question) => {
    if (!question || typeof question !== "object") return false;
    const name = normalizeValue(question.name ?? question.label);
    return name.toLowerCase() === expectedName.toLowerCase();
  });

  return match && typeof match === "object" && "value" in match
    ? normalizeValue(match.value)
    : normalizeValue(match);
};

const entryTypeRaw = questionValue(FIELD_IDS.entryType, "Entry Type");
const entryType =
  entryTypeRaw.toLowerCase() === "linkedin"
    ? "LinkedIn"
    : entryTypeRaw.toLowerCase() === "external"
      ? "External"
      : entryTypeRaw;

if (!["LinkedIn", "External"].includes(entryType)) {
  throw new Error(`Fillout submission has an invalid Entry Type: "${entryTypeRaw}".`);
}

const parsed = {
  entryType,
  linkedinJobUrl: questionValue(FIELD_IDS.linkedinJobUrl, "LinkedIn Job URL"),
  companyName: questionValue(FIELD_IDS.companyName, "Company Name"),
  jobTitle: questionValue(FIELD_IDS.jobTitle, "Job Title"),
  jobDescription: questionValue(FIELD_IDS.jobDescription, "Job Description"),
  jobUrl: questionValue(FIELD_IDS.jobUrl, "Job URL"),
  location: questionValue(FIELD_IDS.location, "Location"),
  contractType: questionValue(FIELD_IDS.contractType, "Contract Type"),
  publishedAt: questionValue(FIELD_IDS.publishedAt, "Published Date"),
  jobId: questionValue(FIELD_IDS.jobId, "External Job ID"),
};

if (entryType === "LinkedIn" && !parsed.linkedinJobUrl) {
  throw new Error("LinkedIn Job URL is required for LinkedIn entries.");
}

if (entryType === "External") {
  for (const [field, label] of [
    ["companyName", "Company Name"],
    ["jobTitle", "Job Title"],
    ["jobDescription", "Job Description"],
    ["jobUrl", "Job URL"],
  ]) {
    if (!parsed[field]) {
      throw new Error(`${label} is required for External entries.`);
    }
  }
}

return [{
  json: {
    ...parsed,
    filloutSubmissionId: submission.submissionId ?? submission.id ?? "",
    filloutFormId: submission.formId ?? "",
    filloutSubmittedAt: submission.submissionTime ?? submission.createdAt ?? "",
  },
  pairedItem: { item: 0 },
}];
